                    raise ExprError("division by zero", op[2])
                result = result / rhs
            else:
                if rhs == 0:
                    raise ExprError("modulo by zero", op[2])
                result = result % rhs
        return result

    def _unary(self) -> float:
        if self._accept("-") is not None:
            return -self._unary()
        return self._power()

    def _power(self) -> float:
        base = self._primary()
